"""Assemble compositions/<id>.html from scenes/<id>.js (scene code) + scenes/_head.html.
Scene file first line: // @scene <id> <duration> <title>"""
import glob, os, re
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
head = open(os.path.join(ROOT, 'scenes/_head.html')).read()
for f in sorted(glob.glob(os.path.join(ROOT, 'scenes/s*.js'))):
    src = open(f).read(); m = re.match(r'// @scene (\S+) (\S+) (.*)', src)
    sid, dur, title = m.group(1), m.group(2), m.group(3)
    html = f'''<!doctype html>
<!-- AISLE 9 Ep1, {title}. Generated by scenes/gen.py from scenes/{sid}.js: edit that file, not this one. -->
<html lang="en"><head><title>{title}</title>
{head}</head><body>
<div id="root" data-composition-id="{sid}" data-start="0" data-duration="{dur}" data-width="1920" data-height="1080">
 <div id="stage" class="clip" data-start="0" data-duration="{dur}" data-track-index="0"></div>
</div>
<script>
{src}
</script></body></html>
'''
    out = os.path.join(ROOT, 'compositions', os.path.basename(f)[:-3] + '.html')
    open(out, 'w').write(html); print('wrote', os.path.relpath(out, ROOT))
